function runOrder(tests) {
  const done = new Set();
  const order = [];
  const pending = tests.map(t => ({ name: t.name, priority: t.priority ?? 0, dependsOn: t.dependsOn ?? [] }));
  while (pending.length) {
    const ready = pending.filter(t => t.dependsOn.every(d => done.has(d)));
    if (!ready.length) throw new Error('cycle');
    ready.sort((x, y) => x.priority - y.priority || x.name.localeCompare(y.name));
    const next = ready[0];
    order.push(next.name);
    done.add(next.name);
    pending.splice(pending.indexOf(next), 1);
  }
  return order;
}

coding.prompt:
Given tests `{ name, dependsOn = [] }` and the set of tests that **failed** when run, write `outcomes(tests, failed)` returning an object mapping each name to `'pass'`, `'fail'` or `'skip'`. A test is skipped if any test it depends on (directly or indirectly) failed or was skipped; skipped tests never run, so they cannot be in `failed` with any effect.

```js
outcomes([{ name: 'create' }, { name: 'edit', dependsOn: ['create'] }], ['create'])
// { create: 'fail', edit: 'skip' }
```

coding.solution:
function outcomes(tests, failed) {
  const byName = Object.fromEntries(tests.map(t => [t.name, t.dependsOn || []]));
  const failedSet = new Set(failed);
  const memo = {};
  function resolve(name) {
    if (memo[name]) return memo[name];
    const deps = byName[name] || [];
    const blocked = deps.some(d => resolve(d) !== 'pass');
    memo[name] = blocked ? 'skip' : failedSet.has(name) ? 'fail' : 'pass';
    return memo[name];
  }
  for (const t of tests) resolve(t.name);
  return memo;
}
